/**
 * @distilled.cloud/netbird -- NetBird SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from NetBird's OpenAPI description in
 * `specs/openapi.yml`. Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as NetBird from "@distilled.cloud/netbird";
 *
 * const policies = yield* NetBird.listPolicies({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { NetBirdProtocol, type NetBirdOpError, type NetBirdOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations and their request and response types are importable from the package root. The
// service-local error classes shadow the shared ones from ./errors.ts, because the operations
// raise the service-local classes.
export * from "./services/netbird.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/netbird.ts";
